    public Map<String, Object> parseWsTrade(Map<String, Object> trade, Map<String, Object> market)
    {
        //
        // public trade (protobuf)
        //    {
        //        "p": "20382.70",
        //        "v": "0.043800",
        //        "S": 1,
        //        "t": 1678593222456,
        //    }
        // private trade
        //    {
        //        "S": 1,
        //        "T": 1661938980268,
        //        "c": "",
        //        "i": "c079b0fcb80a46e8b128b281ce4e4f38",
        //        "m": 1,
        //        "p": "1.008",
        //        "st": 0,
        //        "t": "4079b1522a0b40e7919f609e1ea38d44",
        //        "v": "5"
        //    }
        //
        //   d: {
        //       p: '1.0005',
        //       v: '5.71',
        //       a: '5.712855',
        //       S: 1,
        //       T: 1714325698237,
        //       t: 'edafcd9fdc2f426e82443d114691f724',
        //       c: '',
        //       i: 'C02__413321238354677760043',
        //       m: 0,
        //       st: 0,
        //       n: '0.005712855',
        //       N: 'USDT'
        //   }
        // protobuf
        //
        //     {
        //        price: "3.6962",
        //        quantity: "1",
        //        amount: "3.6962",
        //        tradeType: 2,
        //        tradeId: "505979017439002624X1",
        //        orderId: "C02__505979017439002624115",
        //        feeAmount: "0.0003998377369698171",
        //        feeCurrency: "MX",
        //        time: 1736417034280
        //      }
        //
        Long timestamp = (Long) this.safeInteger2(trade, "T", "time");
        String tradeId = this.safeString2(trade, "t", "tradeId");
        if (java.util.Objects.equals(timestamp, null))
        {
            timestamp = (Long) this.safeInteger(trade, "t");
            tradeId = null;
        }
        String priceString = this.safeString2(trade, "p", "price");
        String amountString = this.safeString2(trade, "v", "quantity");
        String rawSide = this.safeString2(trade, "S", "tradeType");
        String side = "sell";
        if (java.util.Objects.equals(rawSide, "1"))
        {
            side = "buy";
        }
        Long isMaker = this.safeInteger(trade, "m");
        String feeAmount = this.safeString2(trade, "n", "feeAmount");
        String feeCurrencyId = this.safeString2(trade, "N", "feeCurrency");
        return (Map<String, Object>) (this.safeTrade(Helpers.newMap(
            "info", trade,
            "id", tradeId,
            "order", this.safeString2(trade, "i", "orderId"),
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "symbol", this.safeSymbol(null, market, (String) null, (String) null),
            "type", null,
            "side", side,
            "takerOrMaker", (((!java.util.Objects.equals(isMaker, null) && (isMaker == null || isMaker != 0)))) ? "maker" : "taker",
            "price", priceString,
            "amount", amountString,
            "cost", this.safeString(trade, "amount"),
            "fee", new HashMap<String, Object>() {{
                put( "cost", feeAmount );
                put( "currency", Mexc.this.safeCurrencyCode((String) (feeCurrencyId), (Map<String, Object>) null) );
            }}
        ), market));
    }

